def _parse(body):
    i = 0
    neg = False
    if body.startswith("^"):
        neg, body = True, body[1:]
    items = []
    def one(i):
        ch = body[i]
        if ch == "\\":
            if i + 1 >= len(body): raise ValueError("dangling escape")
            n = body[i+1]
            if n == "x":
                if i + 3 >= len(body): raise ValueError("bad hex")
                return chr(int(body[i+2:i+4], 16)), i + 4
            m = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", "]": "]", "-": "-", "^": "^"}
            if n not in m: raise ValueError("bad escape")
            return m[n], i + 2
        return ch, i + 1
    while i < len(body):
        c1, j = one(i)
        if j < len(body) and body[j] == "-" and j + 1 < len(body):
            c2, k = one(j + 1)
            if ord(c2) < ord(c1): raise ValueError("reversed range")
            items.append((ord(c1), ord(c2))); i = k
        else:
            items.append((ord(c1), ord(c1))); i = j
    return neg, items

def coalesce_classes(pattern):
    neg, items = _parse(pattern)
    items.sort()
    merged = []
    for a, b in items:
        if merged and a <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    def esc(cp, first, last):
        ch = chr(cp)
        if ch == "\n": return "\\n"
        if ch == "\t": return "\\t"
        if ch == "\r": return "\\r"
        if ch == "\\": return "\\\\"
        if ch == "]": return "\\]"
        if ch == "^" and first: return "\\^"
        if ch == "-" and not first and not last: return "\\-"
        return ch
    out = []
    flat = []
    for a, b in merged:
        n = b - a + 1
        if n >= 3: flat.append(("r", a, b))
        else: flat += [("c", a, a)] + ([("c", b, b)] if n == 2 else [])
    total = len(flat)
    for idx, t in enumerate(flat):
        first = idx == 0 and not neg
        last = idx == total - 1
        if t[0] == "r":
            out.append(esc(t[1], first, False) + "-" + esc(t[2], False, last))
        else:
            out.append(esc(t[1], first, last))
    return ("^" if neg else "") + "".join(out)
